entries[20506] = { ["name"] = "Muster: Feuerspuckerarmschienen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (300)\nBenötigt Zirkel des Cenarius\n- Freundlich\nBenutzen: Lehrt Euch die Herstellung von Feuerspuckerarmschienen.\nFeuerspuckerarmschienen\nWird beim Anlegen gebunden\nHandgelenke Kette\n160 Rüstung\n+9 Beweglichkeit\n+9 Intelligenz\nHaltbarkeit 40 / 40\nBenötigt Stufe 57\nAnlegen: Stellt alle 5 Sek. 5 Mana wieder her.\nAnlegen: Erhöht die Zaubermacht um 8.\nBenötigt Leichter Silithidenknochenpanzer , Silithidenchitin (20), Essenz des Feuers (2)" }
