entries[20970] = { ["name"] = "Vorlage: Anhänger des Achatschilds", ["text"] = "Benötigt Juwelenschleifen (120)\nBenutzen: Lehrt Euch die Herstellung eines Anhängers des Achatschilds.\nAnhänger des Achatschilds\nWird beim Anlegen gebunden\nHals\n+4 Stärke\n+4 Ausdauer\nBenötigt Stufe 26\nAnlegen: Erhöht Verteidigungswertung um 6.\nBenutzen: Gewährt nahen Gruppenmitgliedern 30 min lang 10 zusätzliche Ausdauer.\n10 AufladungenBenötigt Moosachat , Bronzefassung" }
