entries[21128] = { ["name"] = "Stab der Qirajipropheten", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n129 - 214 Schaden Tempo 2.90\n(59.14 Schaden pro Sekunde)\n+21 Ausdauer\n+26 Intelligenz\n+8 Willenskraft\n+10 Arkanwiderstand\n+10 Feuerwiderstand\n+10 Naturwiderstand\n+10 Frostwiderstand\n+10 Schattenwiderstand\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nErhöht die Angriffskraft um 62 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Zaubermacht um 56.\nAnlegen: Verleiht Zaubersprüchen, die erfolgreich Schaden zufügen, 8 sec lang eine Chance den Zauberwiderstand ihrer Ziele um 50 zu senken. (Procchance: 15%)" }
