entries[21268] = { ["name"] = "Gesegneter Qirajikriegshammer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n89 - 166 Schaden Tempo 2.10\n(60.71 Schaden pro Sekunde)\n70 Rüstung\n+12 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 60\nErhöht die Angriffskraft um 82 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Angriffskraft um 20.\nAnlegen: Erhöht Verteidigungswertung um 12.\n\"Diese Waffe wurde mit Elementium erfüllt und verstärkt.\"" }
entries[21269] = { ["name"] = "Gesegneter Qirajischild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n3407 Rüstung\n73 Blocken\n+20 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 60\nAnlegen: Erhöht Eure Blockwertung um 13.\nAnlegen: Erhöht den Blockwert Eures Schildes um 30.\nAnlegen: Erhöht Verteidigungswertung um 12.\n\"Dieser Schild wurde mit Elementium erfüllt und verstärkt.\"" }
