entries[21548] = { ["name"] = "Muster: Sturmschleierhandschuhe", ["text"] = "Benötigt Lederverarbeitung (300)\nBenutzen: Lehrt Euch die Herstellung von Sturmschleierhandschuhen.\nSturmschleierhandschuhe\nWird beim Anlegen gebunden\nHände Leder\n99 Rüstung\nHaltbarkeit 35 / 35\nBenötigt Stufe 50\nAnlegen: Erhöht die kritische Trefferwertung um 19.\nAnlegen: Erhöht die Trefferwertung um 10.\n\nSturmschleier (0/4)\nSturmschleierrüstung\nSturmschleierhose\nSturmschleierschultern\nSturmschleierhandschuhe\nBenötigt Verzaubertes Leder (6), Essenz der Luft (4), Eisenweberseide (2)" }
